import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate hoy = LocalDate.now();
        LocalDate navidad = LocalDate.of(2025, 12, 25);
        long diasRestantes = ChronoUnit.DIAS.between(hoy, navidad);
        System.out.println("Hoy: " + hoy);
        System.out.println("Navidad: " + navidad);
        if (diasRestantes > 0) {
            System.out.println("Faltan " + diasRestantes + " días para Navidad");
        } else if (diasRestantes == 0) {
            System.out.println("¡Hoy es Navidad!");
        } else {
            System.out.println("Navidad ya pasó hace " + Math.abs(diasRestantes) + " días");
        }
    }
}

